static void create_status_dots(void){const unsigned colors[][3]={{28,163,96},{142,150,164},{28,161,182},{225,160,54},{167,172,182}};for(unsigned c=0;c<5;++c){GdkPixbuf *p=gdk_pixbuf_new(GDK_COLORSPACE_RGB,TRUE,8,12,12);guchar *pixels=gdk_pixbuf_get_pixels(p);int stride=gdk_pixbuf_get_rowstride(p);for(unsigned y=0;y<12;++y)for(unsigned x=0;x<12;++x){unsigned covered=0;for(unsigned sy=0;sy<4;++sy)for(unsigned sx=0;sx<4;++sx){double dx=x+(sx+.5)/4-6,dy=y+(sy+.5)/4-6;if(dx*dx+dy*dy<=11)++covered;}guchar *pixel=pixels+y*stride+x*4;pixel[0]=(guchar)colors[c][0];pixel[1]=(guchar)colors[c][1];pixel[2]=(guchar)colors[c][2];pixel[3]=(guchar)(covered*255/16);}status_dots[c]=p;}}
