static bool row_matches(size_t index,const char *fold){if(!*fold)return true;for(unsigned col=0;col<10;++col){char text[512];desktop_cell(&app,index,col,text,sizeof(text));char *value=g_utf8_casefold(text,-1);bool match=strstr(value,fold)!=NULL;g_free(value);if(match)return true;}return false;}
