static char *choose_file(bool save,const char *name){GtkWidget *dialog=gtk_file_chooser_dialog_new(tr(save ? "Save" : "Open profile",save ? "Сохранить" : "Открыть профиль"),GTK_WINDOW(window),save ? GTK_FILE_CHOOSER_ACTION_SAVE : GTK_FILE_CHOOSER_ACTION_OPEN,tr("Cancel","Отмена"),GTK_RESPONSE_CANCEL,tr(save ? "Save" : "Open",save ? "Сохранить" : "Открыть"),GTK_RESPONSE_ACCEPT,NULL);if(save){gtk_file_chooser_set_do_overwrite_confirmation(GTK_FILE_CHOOSER(dialog),TRUE);gtk_file_chooser_set_current_name(GTK_FILE_CHOOSER(dialog),name);}char *path=NULL;if(gtk_dialog_run(GTK_DIALOG(dialog))==GTK_RESPONSE_ACCEPT && !finishing && !app.closing)path=gtk_file_chooser_get_filename(GTK_FILE_CHOOSER(dialog));gtk_widget_destroy(dialog);return path;}
