static void ui_settings(bool save){if(!app.settings[0])return;char *path=g_strconcat(app.settings,".ui",NULL);GKeyFile *key=g_key_file_new();if(save){gint width,height;gtk_window_get_size(GTK_WINDOW(window),&width,&height);g_key_file_set_integer(key,"window","width",width);g_key_file_set_integer(key,"window","height",height);for(gint i=0;i<10;++i){char name[16];snprintf(name,sizeof(name),"column%d",i);g_key_file_set_integer(key,"table",name,gtk_tree_view_column_get_width(gtk_tree_view_get_column(GTK_TREE_VIEW(table),i)));}gsize length;char *data=g_key_file_to_data(key,&length,NULL);g_file_set_contents(path,data,length,NULL);g_free(data);}else if(g_key_file_load_from_file(key,path,G_KEY_FILE_NONE,NULL)){gint width=g_key_file_get_integer(key,"window","width",NULL),height=g_key_file_get_integer(key,"window","height",NULL);if(width>=760 && width<=3840 && height>=500 && height<=2160)gtk_window_set_default_size(GTK_WINDOW(window),width,height);for(gint i=0;i<10;++i){char name[16];snprintf(name,sizeof(name),"column%d",i);gint width=g_key_file_get_integer(key,"table",name,NULL);if(width>=40 && width<=1200)gtk_tree_view_column_set_fixed_width(gtk_tree_view_get_column(GTK_TREE_VIEW(table),i),width);}}g_key_file_free(key);g_free(path);}
static void remap_profile(void){remapping=true;GtkWidget *dialog=gtk_dialog_new_with_buttons(tr("Profile interface unavailable","Интерфейс профиля недоступен"),GTK_WINDOW(window),GTK_DIALOG_MODAL,tr("Cancel","Отмена"),GTK_RESPONSE_CANCEL,tr("Use selected interface","Использовать выбранный интерфейс"),GTK_RESPONSE_ACCEPT,NULL);GtkWidget *combo=gtk_combo_box_text_new();for(size_t i=0;i<app.interface_count;++i)gtk_combo_box_text_append_text(GTK_COMBO_BOX_TEXT(combo),app.interfaces[i].name);gtk_combo_box_set_active(GTK_COMBO_BOX(combo),app.selected<app.interface_count ? (gint)app.selected:0);gtk_box_pack_start(GTK_BOX(gtk_dialog_get_content_area(GTK_DIALOG(dialog))),combo,FALSE,FALSE,12);gtk_widget_show_all(dialog);gint response=gtk_dialog_run(GTK_DIALOG(dialog));if(!finishing && !app.closing)desktop_profile_rebind(&app,response==GTK_RESPONSE_ACCEPT ? (size_t)gtk_combo_box_get_active(GTK_COMBO_BOX(combo)):SIZE_MAX);gtk_widget_destroy(dialog);remapping=false;if(app.profile_changed){populate();app.profile_changed=false;}update();}
static gboolean close_window(GtkWidget *sender,GdkEvent *event,gpointer data){(void)sender;(void)event;(void)data;ui_settings(true);finishing=true;desktop_stop(&app);GList *windows=gtk_window_list_toplevels();for(GList *i=windows;i;i=i->next)if(GTK_IS_DIALOG(i->data) && gtk_window_get_transient_for(GTK_WINDOW(i->data))==GTK_WINDOW(window))gtk_dialog_response(GTK_DIALOG(i->data),GTK_RESPONSE_CANCEL);g_list_free(windows);gtk_widget_set_sensitive(window,FALSE);return TRUE;}
